import numpy as np
import mujoco
from scipy.spatial.transform import Rotation, Slerp
from PIL import Image

class Controller:
    def __init__(self,s):
        self.s=s; self.m=s.model; self.d=s.data
        self.sid=s.env.robots[0].eef_site_id['right']
        self.jids=np.array([self.m.joint(f'robot0_joint{i}').id for i in range(1,8)])
        self.qids=self.m.jnt_qposadr[self.jids]; self.vids=self.m.jnt_dofadr[self.jids]
        self.kd=mujoco.MjData(self.m)
        self.grip=-1
    def pos(self): return self.d.site_xpos[self.sid].copy()
    def rot(self): return self.d.site_xmat[self.sid].reshape(3,3).copy()
    def obj(self,name='brewed_coffee'): return self.d.xpos[self.m.body(name+'_main').id].copy()
    def ik(self,p,R,seed=None):
        kd=self.kd; kd.qpos[:]=self.d.qpos
        q=self.d.qpos[self.qids].copy() if seed is None else seed.copy()
        for _ in range(80):
            kd.qpos[self.qids]=q; mujoco.mj_kinematics(self.m,kd); mujoco.mj_comPos(self.m,kd)
            ep=np.asarray(p)-kd.site_xpos[self.sid]
            er=Rotation.from_matrix(R@kd.site_xmat[self.sid].reshape(3,3).T).as_rotvec()
            e=np.r_[ep,er]
            if np.linalg.norm(ep)<0.00015 and np.linalg.norm(er)<0.001: break
            jp=np.zeros((3,self.m.nv)); jr=jp.copy(); mujoco.mj_jacSite(self.m,kd,jp,jr,self.sid)
            J=np.vstack([jp[:,self.vids],jr[:,self.vids]])
            dq=J.T@np.linalg.solve(J@J.T+np.eye(6)*0.00005,e)
            q+=dq*min(1,0.15/max(np.max(np.abs(dq)),1e-8))
            q=np.clip(q,self.m.jnt_range[self.jids,0]+0.01,self.m.jnt_range[self.jids,1]-0.01)
        return q
    def step(self,q=None,base=None,torso=0):
        a=np.zeros(13); a[:7]=self.d.qpos[self.qids] if q is None else q; a[7]=self.grip; a[12]=-1
        if base is not None: a[8:11]=base; a[12]=1
        a[11]=torso
        return self.s.step(a)
    def hold(self,n=20):
        q=self.s.targets[:7].copy()
        for _ in range(n): self.step(q)
    def move(self,p,R=None,n=60,settle=10):
        p=np.asarray(p); R=self.rot() if R is None else np.asarray(R)
        p0=self.pos(); r0=self.rot(); sl=Slerp([0,1],Rotation.from_matrix(np.stack([r0,R])))
        q=self.d.qpos[self.qids].copy()
        for i in range(n):
            t=(i+1)/n; t=t*t*(3-2*t)
            q=self.ik(p0+(p-p0)*t,sl(t).as_matrix(),q)
            self.step(q)
        self.hold(settle)
        print('move',len(self.s.actions),'eef',self.pos(),'object',self.obj(),'error',np.linalg.norm(p-self.pos()),flush=True)
    def snap(self,name): Image.fromarray(self.s.render_grid()).save('/app/output/'+name+'.png')
